components.css:
.ds-btn-primary { display: inline-flex; align-items: center; justify-content: center; gap: 6px; height: 36px; padding: 0 16px; border: 0; border-radius: 8px; font-family: system-ui, -apple-system, 'Segoe UI', 'PingFang SC', 'Hiragino Sans GB', 'Microsoft YaHei', sans-serif; font-size: 14px; line-height: 20px; cursor: pointer; transition: background-color .15s cubic-bezier(.4,0,.2,1), border-color .15s, color .15s; background: var(--color-accent, #0f172a); color: var(--color-on-accent, #ffffff); }
.ds-btn-primary:hover { background: color-mix(in srgb, var(--color-accent, #0f172a) 90%, transparent); }
.ds-btn-primary:focus-visible { outline: 2px solid var(--color-muted, #475569); outline-offset: 2px; }
.ds-btn-primary:active { transform: translateY(1px); }
.ds-btn-primary[disabled] { opacity: .5; cursor: not-allowed; }

.ds-btn-secondary { display: inline-flex; align-items: center; justify-content: center; gap: 6px; height: 36px; padding: 0 16px; border: 0; border-radius: 8px; font-family: system-ui, -apple-system, 'Segoe UI', 'PingFang SC', 'Hiragino Sans GB', 'Microsoft YaHei', sans-serif; font-size: 14px; line-height: 20px; cursor: pointer; transition: background-color .15s cubic-bezier(.4,0,.2,1), border-color .15s, color .15s; background: var(--color-surface, #fff); color: var(--color-muted, #475569); border: 1px solid var(--color-border-strong, #cbd5e1); }
.ds-btn-secondary:hover { background: var(--color-surface-2, #f1f5f9); color: var(--color-fg, #0f172a); }
.ds-btn-secondary:focus-visible { outline: 2px solid var(--color-muted, #475569); outline-offset: 2px; }

.ds-btn-icon { display: inline-flex; align-items: center; justify-content: center; width: 36px; height: 36px; border-radius: 8px; background: var(--color-surface, #fff); border: 1px solid var(--color-border, #e2e8f0); color: var(--color-muted, #475569); cursor: pointer; transition: background-color .15s, color .15s; }
.ds-btn-icon:hover { background: var(--color-surface-2, #f1f5f9); color: var(--color-fg, #0f172a); }
.ds-btn-icon:focus-visible { outline: 2px solid var(--color-muted, #475569); outline-offset: 2px; }

.ds-search { display: flex; width: 100%; align-items: center; gap: 8px; font-family: system-ui, -apple-system, 'Segoe UI', 'PingFang SC', 'Hiragino Sans GB', 'Microsoft YaHei', sans-serif; }
.ds-search-field { position: relative; flex: 1; min-width: 0; }
.ds-search-field input { width: 100%; height: 36px; padding: 0 12px; border-radius: 8px; border: 1px solid var(--color-border-strong, #cbd5e1); background: var(--color-surface, #fff); color: var(--color-fg, #0f172a); font-size: 14px; font-family: inherit; outline: none; transition: border-color .15s; }
.ds-search-field input:focus { border-color: var(--color-muted, #475569); }
.ds-search-field input:focus-visible { outline: 2px solid var(--color-muted, #475569); outline-offset: 1px; }
.ds-search-hint { position: absolute; inset: 0 12px 0 12px; display: flex; align-items: center; pointer-events: none; font-size: 14px; color: var(--color-faint, #94a3b8); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ds-search-field input:not(:placeholder-shown) + .ds-search-hint { display: none; }
.ds-search-submit { height: 36px; padding: 0 16px; flex-shrink: 0; border-radius: 8px; border: 0; background: var(--color-accent, #0f172a); color: var(--color-on-accent, #fff); font-size: 14px; font-family: inherit; cursor: pointer; }
.ds-search-submit:hover { background: color-mix(in srgb, var(--color-accent, #0f172a) 90%, transparent); }

.ds-chip { display: inline-flex; align-items: center; height: 32px; padding: 0 16px; border-radius: 9999px; border: 1px solid var(--color-border-strong, #cbd5e1); background: var(--color-surface, #fff); color: var(--color-muted, #475569); font-family: system-ui, -apple-system, 'Segoe UI', 'PingFang SC', 'Hiragino Sans GB', 'Microsoft YaHei', sans-serif; font-size: 14px; cursor: pointer; transition: border-color .15s, color .15s; }
.ds-chip:hover { border-color: var(--color-muted, #475569); color: var(--color-fg, #0f172a); }
.ds-chip:focus-visible { outline: 2px solid var(--color-muted, #475569); outline-offset: 2px; }

.ds-card { display: block; border-radius: 12px; border: 1px solid var(--color-border, #e2e8f0); background: var(--color-surface, #fff); overflow: hidden; text-decoration: none; color: inherit; font-family: system-ui, -apple-system, 'Segoe UI', 'PingFang SC', 'Hiragino Sans GB', 'Microsoft YaHei', sans-serif; transition: box-shadow .15s, border-color .15s; }
.ds-card:hover { box-shadow: 0 4px 6px -1px rgb(0 0 0 / .1), 0 2px 4px -2px rgb(0 0 0 / .1); border-color: var(--color-border-strong, #cbd5e1); }
.ds-card:focus-visible { outline: 2px solid var(--color-muted, #475569); outline-offset: 2px; }
.ds-card-well { aspect-ratio: 3 / 4; background: var(--color-surface-2, #f1f5f9); display: flex; align-items: center; justify-content: center; color: var(--color-ghost, #cbd5e1); font-size: 14px; }
.ds-card-body { padding: 12px; }
.ds-card-meta { font-size: 12px; color: var(--color-faint, #94a3b8); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ds-card-name { font-size: 16px; font-weight: 500; color: var(--color-fg, #0f172a); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ds-card-row { display: flex; align-items: center; justify-content: space-between; margin-top: 8px; }
.ds-card-price { font-size: 16px; font-weight: 600; color: oklch(0.586 0.253 17.585); }
.ds-card-rarity { font-size: 12px; color: var(--color-faint, #94a3b8); }
.ds-card-code { font-size: 12px; color: var(--color-faint, #94a3b8); margin-top: 4px; }
.ds-card-badge { display: inline-block; margin-top: 4px; font-size: 10px; padding: 2px 6px; border-radius: 4px; color: oklch(0.666 0.179 58.318); background: oklch(0.769 0.188 70.08 / .15); }
@media (prefers-color-scheme: dark) { .ds-card-price { color: oklch(0.712 0.194 13.428); } .ds-card-badge { color: oklch(0.828 0.189 84.429); } }

.ds-rows { border: 1px solid var(--color-border, #e2e8f0); border-radius: 12px; background: var(--color-surface, #fff); overflow: hidden; font-family: system-ui, -apple-system, 'Segoe UI', 'PingFang SC', 'Hiragino Sans GB', 'Microsoft YaHei', sans-serif; }
.ds-row { display: flex; align-items: center; gap: 12px; padding: 10px 16px; text-decoration: none; color: inherit; transition: background-color .15s; }
.ds-row + .ds-row { border-top: 1px solid var(--color-border, #e2e8f0); }
.ds-row:hover { background: var(--color-surface-2, #f1f5f9); }
.ds-row-date { width: 112px; flex-shrink: 0; font-size: 12px; color: var(--color-faint, #94a3b8); font-variant-numeric: tabular-nums; }
.ds-row-title { flex: 1; min-width: 0; font-size: 14px; color: var(--color-fg, #0f172a); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ds-badge-pinned { display: inline-block; flex-shrink: 0; font-size: 10px; padding: 2px 6px; border-radius: 4px; color: oklch(0.586 0.253 17.585); background: oklch(0.645 0.246 16.439 / .15); }
@media (prefers-color-scheme: dark) { .ds-badge-pinned { color: oklch(0.712 0.194 13.428); } }

.ds-pager { display: flex; align-items: center; justify-content: center; gap: 4px; font-family: system-ui, -apple-system, 'Segoe UI', 'PingFang SC', 'Hiragino Sans GB', 'Microsoft YaHei', sans-serif; }
.ds-pager-cell, .ds-pager-arrow { display: inline-flex; align-items: center; justify-content: center; height: 36px; min-width: 36px; padding: 0 12px; border-radius: 8px; font-size: 14px; font-family: inherit; background: var(--color-surface, #fff); color: var(--color-muted, #475569); border: 1px solid var(--color-border-strong, #cbd5e1); cursor: pointer; transition: background-color .15s, color .15s; }
.ds-pager-cell:hover, .ds-pager-arrow:hover { background: var(--color-surface-2, #f1f5f9); color: var(--color-fg, #0f172a); }
.ds-pager-cell-active { background: var(--color-accent, #0f172a); color: var(--color-on-accent, #fff); border-color: transparent; font-weight: 600; }
.ds-pager-cell:focus-visible, .ds-pager-arrow:focus-visible { outline: 2px solid var(--color-muted, #475569); outline-offset: 2px; }
@media (max-width: 359px) { .ds-pager-cell, .ds-pager-arrow { min-width: 28px; padding: 0 6px; } }
